const COMPANY_BY_ID: Map<string, Company> = new Map(VERIFIED_COMPANIES.map((c) => [c.id, c]));
const COMPANY_BY_SLUG: Map<string, Company> = new Map(VERIFIED_COMPANIES.map((c) => [c.slug, c]));

/**
 * FK-safe company lookup by UUID or slug.
 * Falls back to VERIFIED_COMPANIES[0] to preserve legacy non-null expectations.
 */
export function findCompany(idOrSlug: string): Company {
  return COMPANY_BY_ID.get(idOrSlug) ?? COMPANY_BY_SLUG.get(idOrSlug) ?? VERIFIED_COMPANIES[0];
}


