// ---------------------------------------------------------------------------
// FK integrity relinking (defense-in-depth).
// Static embeddings above are generated via findCompany(company_id); this loop
// guarantees party.company.id === party.company_id and
// relationship.from_company.id === from_company_id at runtime even if a future
// edit reintroduces an index-based embedding.
// ---------------------------------------------------------------------------
for (const deal of VERIFIED_DEALS) {
  for (const party of deal.parties ?? []) {
    const fixed = COMPANY_BY_ID.get(party.company_id);
    if (fixed) party.company = fixed;
  }
  for (const ds of deal.sources ?? []) {
    const src = VERIFIED_SOURCES.find((s) => s.id === ds.source_id);
    if (src) ds.source = src;
  }
}

for (const rel of VERIFIED_RELATIONSHIPS) {
  const from = COMPANY_BY_ID.get(rel.from_company_id);
  if (from) rel.from_company = from;
  const to = COMPANY_BY_ID.get(rel.to_company_id);
  if (to) rel.to_company = to;
}
